// Isolated install smoke: start <plugin>/bridge/mcp-server.cjs from a temp project folder whose
// .sc4sap/active-profile.txt names the system, talk MCP JSON-RPC over stdio, read-only calls only.
import { spawn } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const [, , pluginDir, projDir, alias, probeObj, extra] = process.argv;
mkdirSync(join(projDir, '.sc4sap'), { recursive: true });
writeFileSync(join(projDir, '.sc4sap', 'active-profile.txt'), alias);

const child = spawn(process.execPath, [join(pluginDir, 'bridge', 'mcp-server.cjs')], { cwd: projDir, stdio: ['pipe', 'pipe', 'pipe'] });
let buf = '', id = 0;
const waiting = new Map();
let stderr = '';
child.stderr.on('data', (d) => { stderr += d; });
child.stdout.on('data', (d) => {
  buf += d;
  let nl;
  while ((nl = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, nl).trim(); buf = buf.slice(nl + 1);
    if (!line) continue;
    let msg; try { msg = JSON.parse(line); } catch { continue; }
    if (msg.id !== undefined && waiting.has(msg.id)) { waiting.get(msg.id)(msg); waiting.delete(msg.id); }
  }
});
const call = (method, params, ms = 120000) => new Promise((res, rej) => {
  const my = ++id;
  const t = setTimeout(() => rej(new Error(`timeout ${method}`)), ms);
  waiting.set(my, (m) => { clearTimeout(t); res(m); });
  child.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: my, method, params }) + '\n');
});
const text = (r) => (r.result?.content || []).map((c) => c.text || '').join('\n');
const out = { alias };
try {
  const init = await call('initialize', { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'iso-smoke', version: '1' } }, 180000);
  out.server = init.result?.serverInfo;
  child.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
  const tl = await call('tools/list', {});
  const tools = tl.result?.tools || [];
  const by = (n) => tools.find((t) => t.name === n);
  out.tools = tools.length;
  out.deleteAdobeForm = !!by('DeleteAdobeForm');
  out.updateProgramPatches = !!by('UpdateProgram')?.inputSchema?.properties?.source_patches;
  out.updateIncludePatches = !!by('UpdateInclude')?.inputSchema?.properties?.source_patches;
  out.tcodeUsageArgs = Object.keys(by('GetTcodeUsage')?.inputSchema?.properties || {});
  const so = await call('tools/call', { name: 'SearchObject', arguments: { object_name: probeObj, maxResults: 5 } });
  out.search = { isError: !!so.result?.isError, hit: text(so).includes(probeObj), head: text(so).slice(0, 160) };
  const names = Array.from({ length: 40 }, (_, i) => `'ZZ_SMOKE_${String(i).padStart(4, '0')}'`).join(', ');
  const sql = `SELECT TABNAME, AS4LOCAL FROM DD02L WHERE TABNAME IN ('T000', ${names})`;
  const q = await call('tools/call', { name: 'GetSqlQuery', arguments: { sql_query: sql, row_number: 5 } });
  out.sql = { longestLine: sql.length, isError: !!q.result?.isError, t000: text(q).includes('T000'), head: text(q).slice(0, 200) };
  if (extra === 'usage') {
    const u = await call('tools/call', { name: 'GetTcodeUsage', arguments: { tcodes: ['VA01', 'SU01'] } });
    out.usage = { isError: !!u.result?.isError, head: text(u).slice(0, 300) };
  }
} catch (e) {
  out.error = e.message;
  out.stderrTail = stderr.slice(-800);
}
console.log(JSON.stringify(out, null, 1));
child.kill();
process.exit(0);

